use std::path::PathBuf;

use anyhow::Result;
use clap::{Parser, Subcommand};
use ni_core::{now_ms, Event, SessionLog};

#[derive(Debug, Parser)]
#[command(name = "ni", version, about = "Minimal, observable coding agent")]
struct Cli {
    #[command(subcommand)]
    command: Option<Command>,
}

#[derive(Debug, Subcommand)]
enum Command {
    /// Inspect and create append-only session logs
    Session {
        #[command(subcommand)]
        command: SessionCommand,
    },
}

#[derive(Debug, Subcommand)]
enum SessionCommand {
    /// Create a session and print its path
    New {
        /// Directory for the session file
        #[arg(long)]
        dir: Option<PathBuf>,
    },
    /// Print the events in a session file
    Show {
        /// Path to a .jsonl session file
        path: PathBuf,
    },
    /// List session files
    List {
        /// Directory containing session files
        #[arg(long)]
        dir: Option<PathBuf>,
    },
}

fn main() -> Result<()> {
    let cli = Cli::parse();
    match cli.command {
        Some(Command::Session { command }) => run_session(command),
        None => {
            print_banner();
            Ok(())
        }
    }
}

fn run_session(command: SessionCommand) -> Result<()> {
    match command {
        SessionCommand::New { dir } => {
            let dir = dir.unwrap_or_else(default_sessions_dir);
            let mut log = SessionLog::create(&dir)?;
            log.append(&Event::SessionStart {
                id: log.id().to_string(),
                cwd: std::env::current_dir()?.display().to_string(),
                model: "unset".into(),
                ts: now_ms(),
            })?;
            println!("{}", log.path().display());
            Ok(())
        }
        SessionCommand::Show { path } => {
            let loaded = ni_core::load(&path)?;
            println!("session  {}", path.display());
            println!("events   {}", loaded.events.len());
            println!("warnings {}", loaded.warnings.len());
            for warning in &loaded.warnings {
                eprintln!("warning: {warning}");
            }
            for event in &loaded.events {
                println!("{:>13}  {}", event.ts(), event.kind());
            }
            Ok(())
        }
        SessionCommand::List { dir } => {
            let dir = dir.unwrap_or_else(default_sessions_dir);
            for path in ni_core::session::list(&dir)? {
                println!("{}", path.display());
            }
            Ok(())
        }
    }
}

fn default_sessions_dir() -> PathBuf {
    if let Ok(home) = std::env::var("NI_HOME") {
        return PathBuf::from(home).join("sessions");
    }
    if let Ok(home) = std::env::var("HOME") {
        return PathBuf::from(home).join(".ni").join("sessions");
    }
    PathBuf::from(".ni").join("sessions")
}

fn print_banner() {
    println!(
        "ni {} · minimal, observable coding agent",
        env!("CARGO_PKG_VERSION")
    );
    println!();
    println!("status   M0 · bootstrap");
    println!("docs     docs/index.html");
    println!("sessions {}", default_sessions_dir().display());
    println!();
    println!("next     ni session new");
    println!("         cargo xtask dashboard");
}

//! Append-only JSONL session storage.
//!
//! A session is a file of one JSON event per line. Appends are flushed
//! immediately; loading tolerates a corrupt tail instead of discarding the
//! whole session.

use std::fs::{self, File, OpenOptions};
use std::io::{BufRead, BufReader, BufWriter, Write};
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicU64, Ordering};

use anyhow::{Context, Result};

use crate::event::{now_ms, Event};

static SESSION_SEQ: AtomicU64 = AtomicU64::new(0);

#[derive(Debug)]
pub struct LoadedSession {
    pub events: Vec<Event>,
    /// Lines that could not be decoded. The rest of the session is still valid.
    pub warnings: Vec<String>,
}

#[derive(Debug)]
pub struct SessionLog {
    id: String,
    path: PathBuf,
    writer: BufWriter<File>,
}

impl SessionLog {
    /// Create a new session file under `dir`.
    pub fn create(dir: &Path) -> Result<Self> {
        fs::create_dir_all(dir)
            .with_context(|| format!("create session directory {}", dir.display()))?;

        let seq = SESSION_SEQ.fetch_add(1, Ordering::Relaxed);
        let id = format!("{}-{}-{}", now_ms(), std::process::id(), seq);
        let path = dir.join(format!("{id}.jsonl"));
        let file = OpenOptions::new()
            .create_new(true)
            .append(true)
            .open(&path)
            .with_context(|| format!("create session file {}", path.display()))?;

        Ok(Self {
            id,
            path,
            writer: BufWriter::new(file),
        })
    }

    pub fn id(&self) -> &str {
        &self.id
    }

    pub fn path(&self) -> &Path {
        &self.path
    }

    /// Append one event and flush it to disk.
    pub fn append(&mut self, event: &Event) -> Result<()> {
        serde_json::to_writer(&mut self.writer, event).context("serialize session event")?;
        self.writer
            .write_all(b"\n")
            .context("write session event")?;
        self.writer.flush().context("flush session event")?;
        Ok(())
    }
}

/// Read a session, reporting undecodable lines as warnings.
pub fn load(path: &Path) -> Result<LoadedSession> {
    let file = File::open(path).with_context(|| format!("open session file {}", path.display()))?;
    let reader = BufReader::new(file);

    let mut events = Vec::new();
    let mut warnings = Vec::new();

    for (index, line) in reader.lines().enumerate() {
        let line = line.with_context(|| format!("read line {}", index + 1))?;
        if line.trim().is_empty() {
            continue;
        }
        match serde_json::from_str::<Event>(&line) {
            Ok(event) => events.push(event),
            Err(error) => warnings.push(format!("line {}: {error}", index + 1)),
        }
    }

    Ok(LoadedSession { events, warnings })
}

/// List session files in `dir`, sorted by name.
pub fn list(dir: &Path) -> Result<Vec<PathBuf>> {
    if !dir.is_dir() {
        return Ok(Vec::new());
    }

    let mut paths = Vec::new();
    for entry in
        fs::read_dir(dir).with_context(|| format!("read session directory {}", dir.display()))?
    {
        let entry = entry?;
        let path = entry.path();
        if path.extension().is_some_and(|ext| ext == "jsonl") {
            paths.push(path);
        }
    }
    paths.sort();
    Ok(paths)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::event::{Event, ToolCall, Usage};

    fn temp_dir(tag: &str) -> PathBuf {
        static COUNTER: AtomicU64 = AtomicU64::new(0);
        let n = COUNTER.fetch_add(1, Ordering::Relaxed);
        let dir = std::env::temp_dir().join(format!("ni-core-{tag}-{}-{n}", now_ms()));
        let _ = fs::remove_dir_all(&dir);
        fs::create_dir_all(&dir).expect("create temp dir");
        dir
    }

    #[test]
    fn round_trip_preserves_events() {
        let dir = temp_dir("roundtrip");
        let mut log = SessionLog::create(&dir).expect("create log");
        let ts = now_ms();

        let events = vec![
            Event::SessionStart {
                id: log.id().to_string(),
                cwd: "/tmp/project".into(),
                model: "test-model".into(),
                ts,
            },
            Event::UserMessage {
                text: "fix the failing test".into(),
                ts,
            },
            Event::AssistantMessage {
                text: "reading the test".into(),
                reasoning: Some("need the failure output first".into()),
                tool_calls: vec![ToolCall {
                    id: "call-1".into(),
                    name: "read".into(),
                    input: serde_json::json!({"path": "src/lib.rs"}),
                }],
                ts,
            },
            Event::ToolResult {
                call_id: "call-1".into(),
                ok: true,
                output: "fn main() {}".into(),
                ts,
            },
            Event::TurnEnd {
                usage: Usage {
                    input_tokens: 120,
                    output_tokens: 30,
                    cached_tokens: 80,
                    reasoning_tokens: 10,
                },
                ts,
            },
        ];

        for event in &events {
            log.append(event).expect("append");
        }

        let loaded = load(log.path()).expect("load");
        assert_eq!(loaded.events, events);
        assert!(loaded.warnings.is_empty());
        assert_eq!(list(&dir).expect("list"), vec![log.path().to_path_buf()]);

        fs::remove_dir_all(dir).expect("cleanup");
    }

    #[test]
    fn corrupt_tail_is_a_warning_not_a_failure() {
        let dir = temp_dir("corrupt");
        let path = dir.join("session.jsonl");
        let good = serde_json::to_string(&Event::UserMessage {
            text: "hello".into(),
            ts: 1,
        })
        .expect("serialize");
        fs::write(&path, format!("{good}\n{{ not json }}\n")).expect("write fixture");

        let loaded = load(&path).expect("load");
        assert_eq!(loaded.events.len(), 1);
        assert_eq!(loaded.warnings.len(), 1);
        assert!(loaded.warnings[0].starts_with("line 2:"));

//! Durable session events.
//!
//! Events are the only representation of a session that survives the process.
//! The in-memory conversation is a projection of these events; if something is
//! not appended here, it does not exist after the process exits.

use std::time::{SystemTime, UNIX_EPOCH};

use serde::{Deserialize, Serialize};

/// Milliseconds since the Unix epoch.
pub type Timestamp = u64;

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ToolCall {
    pub id: String,
    pub name: String,
    #[serde(default)]
    pub input: serde_json::Value,
}

#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
pub struct Usage {
    #[serde(default)]
    pub input_tokens: u64,
    #[serde(default)]
    pub output_tokens: u64,
    #[serde(default)]
    pub cached_tokens: u64,
    #[serde(default)]
    pub reasoning_tokens: u64,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum Event {
    SessionStart {
        id: String,
        cwd: String,
        model: String,
        ts: Timestamp,
    },
    UserMessage {
        text: String,
        ts: Timestamp,
    },
    AssistantMessage {
        #[serde(default)]
        text: String,
        #[serde(default, skip_serializing_if = "Option::is_none")]
        reasoning: Option<String>,
        #[serde(default)]
        tool_calls: Vec<ToolCall>,
        ts: Timestamp,
    },
    ToolResult {
        call_id: String,
        ok: bool,
        output: String,
        ts: Timestamp,
    },
    TurnEnd {
        #[serde(default)]
        usage: Usage,
        ts: Timestamp,
    },
    Compaction {
        summary: String,
        /// Number of events replaced by this compaction.
        upto: u64,
        ts: Timestamp,
    },
    SessionEnd {
        ts: Timestamp,
    },
}

impl Event {
    /// Stable name used in logs and tests.
    pub fn kind(&self) -> &'static str {
        match self {
            Self::SessionStart { .. } => "session_start",
            Self::UserMessage { .. } => "user_message",
            Self::AssistantMessage { .. } => "assistant_message",
            Self::ToolResult { .. } => "tool_result",
            Self::TurnEnd { .. } => "turn_end",
            Self::Compaction { .. } => "compaction",
            Self::SessionEnd { .. } => "session_end",
        }
    }

    pub fn ts(&self) -> Timestamp {
        match self {
            Self::SessionStart { ts, .. }
            | Self::UserMessage { ts, .. }
            | Self::AssistantMessage { ts, .. }
            | Self::ToolResult { ts, .. }
            | Self::TurnEnd { ts, .. }
            | Self::Compaction { ts, .. }
            | Self::SessionEnd { ts } => *ts,
        }
    }
}

pub fn now_ms() -> Timestamp {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis() as Timestamp
}

